    "id": {
      "type": "string",
      "pattern": "^[a-f0-9]{32}$",
      "description": "ID intern opac, 32 caractere hexazecimale mici; nu este GTIN."
    },
    "active": {
      "const": false,
      "description": "Starea activării contului/aplicației. În listările SQL este 0/1; rezultatul suspendării folosește boolean."
    }
  },
  "required": [
    "id",
    "active"
